#include "unity.h"
#include "header.h"
#include "helpers.h"

// Dependency: swap
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Dependency: partition (simple Lomuto partition for test)
int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j <= high - 1; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return i + 1;
}

// Target: quickSort
void quickSort(int arr[], int low, int high)
{
    if (low < high) {
        int i = partition(arr, low, high);
        quickSort(arr, low, i - 1);
        quickSort(arr, i + 1, high);
    }
}

// Helper: check if array is sorted in non-decreasing order
int helper_is_sorted(int* arr, int length) {
    for (int i = 1; i < length; ++i) {
        if (arr[i-1] > arr[i]) return 0;
    }
    return 1;
}

// Helper: assert two arrays are equal
void helper_assert_array_equal(int* arr1, int* arr2, int length) {
    for (int i = 0; i < length; ++i) {
        TEST_ASSERT_EQUAL_INT(arr1[i], arr2[i]);
    }
}

void setUp(void) { }
void tearDown(void) { }

void test_quickSort_sorts_array_in_place(void) {
    int arr[] = {5, 2, 9, 1, 5, 6};
    int expected[] = {1, 2, 5, 5, 6, 9};
    int len = sizeof(arr)/sizeof(arr[0]);
    quickSort(arr, 0, len - 1);
    helper_assert_array_equal(arr, expected, len);
    TEST_ASSERT_TRUE(helper_is_sorted(arr, len));
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(test_quickSort_sorts_array_in_place);
    return UNITY_END();
}

